package org.mockito.internal.stubbing.answers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.exceptions.Reporter;
import org.mockito.internal.invocation.Invocation;
import org.mockito.internal.stubbing.answers.DoesNothing;
import org.mockito.internal.stubbing.answers.Returns;
import org.mockito.internal.stubbing.answers.ThrowsException;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

public class AnswersValidator_validate_TriageGen1Test {

    private AnswersValidator validator;

    @Before
    public void setUp() {
        // We use a spy to verify that the internal private/protected validate methods are called
        validator = spy(new AnswersValidator());
    }

    @Test
    public void testValidate_WithThrowsException() {
        ThrowsException answer = spy(new ThrowsException());
        Invocation invocation = spy(new Invocation() {});

        validator.validate(answer, invocation);

        verify(validator, times(1)).validateException(answer, invocation);
        verify(validator, times(0)).validateReturnValue(org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
        verify(validator, times(0)).validateDoNothing(org.mockito.ArgumentMatchers.any());
    }

    @Test
    public void testValidate_WithReturns() {
        Returns<?> answer = spy(new Returns<>(null));
        Invocation invocation = spy(new Invocation() {});

        validator.validate(answer, invocation);

        verify(validator, times(0)).validateException(org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
        verify(validator, times(1)).validateReturnValue(answer, invocation);
        verify(validator, times(0)).validateDoNothing(org.mockito.ArgumentMatchers.any());
    }

    @Test
    public void testValidate_WithDoesNothing() {
        DoesNothing answer = spy(new DoesNothing());
        Invocation invocation = spy(new Invocation() {});

        validator.validate(answer, invocation);

        verify(validator, times(0)).validateException(org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
        verify(validator, times(0)).validateReturnValue(org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
        verify(validator, times(1)).validateDoNothing(answer, invocation);
    }

    @Test
    public void testValidate_WithOtherAnswerType() {
        Answer<?> answer = new Answer<Object>() {
            @Override
            public Object answer(Invocation invocation) throws Throwable {
                return null;
            }
        };
        Invocation invocation = spy(new Invocation() {});

        validator.validate(answer, invocation);

        // Ensure no validation methods are called for unknown types
        verify(validator, times(0)).validateException(org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
        verify(validator, times(0)).validateReturnValue(org.mockito.ArgumentMatchers.any(), org.mockito.ArgumentMatchers.any());
        verify(validator, times(0)).validateDoNothing(org.mockito.ArgumentMatchers.any());
    }
}
